/**
 * Runway Gantt rundown queries — per-client extractClientRundown.
 *
 * Returns a Map<clientId, ClientRundownData> keyed by client.id.
 * A null value in the map means extractClientRundown threw for that client.
 *
 * N+1 acknowledged: ~7-12 clients × ~5-15 top-level projects ≈ 35-180
 * sub-queries + weekItem batches. Accepted for initial wire-up.
 * Halt condition: dev page load >5s.
 */

import { asc, isNull, eq } from "drizzle-orm";
import { getRunwayDb } from "@/lib/db/runway";
import { clients, projects as projectsTable } from "@/lib/db/runway-schema";
import { extractClientRundown } from "@/lib/runway/gantt/server";
import type { ClientRundownData } from "@/lib/runway/gantt/types";
import { toISODateString } from "./date-utils";

export async function getClientRundowns(): Promise<Map<string, ClientRundownData>> {
  const db = getRunwayDb();
  const now = new Date();
  const todayISO = toISODateString(now);
  const generatedAt = todayISO;

  // Single batched client fetch, alphabetical
  const allClients = await db
    .select()
    .from(clients)
    .orderBy(asc(clients.name));

  // Single batched top-level project fetch (no parentProjectId)
  const allTopLevel = await db
    .select()
    .from(projectsTable)
    .where(isNull(projectsTable.parentProjectId));

  // Group top-level projects by clientId for O(1) per-client lookup
  const projectsByClient = new Map<string, (typeof allTopLevel)[number][]>();
  for (const p of allTopLevel) {
    const arr = projectsByClient.get(p.clientId) ?? [];
    arr.push(p);
    projectsByClient.set(p.clientId, arr);
  }

  const result = new Map<string, ClientRundownData>();

  for (const client of allClients) {
    const topLevelProjects = projectsByClient.get(client.id) ?? [];
    try {
      const rundown = await extractClientRundown(
        db,
        client,
        topLevelProjects,
        generatedAt,
        todayISO,
      );
      result.set(client.id, rundown);
    } catch (err) {
      console.error(
        `[queries-rundown] extractClientRundown failed for client ${client.id} (${client.name}):`,
        err,
      );
      // null sentinel — AccountSection renders "No active projects." fallback
    }
  }

  return result;
}

