/**
 * Server component wrapper for AccountSection that resolves the
 * GanttSection rendering server-side.
 *
 * GanttTemplate.tsx and themes.ts use react-dom/server + Node's fs —
 * they cannot be imported inside a "use client" component. This wrapper
 * runs server-side, pre-renders each GanttSection as static HTML, and
 * passes the rendered strings into the AccountSection client component.
 *
 * This pattern (server component passes pre-rendered HTML to client
 * component via props) is the Next.js-recommended approach for cases
 * where a client component needs server-only rendered output.
 */

import { renderToStaticMarkup } from "react-dom/server";
import { GanttSection } from "@/lib/runway/gantt/GanttTemplate";
import type { ClientRundownData } from "@/lib/runway/gantt/types";
import type { RenderedClientRundownData } from "../types";
import { AccountSection } from "./account-section";
import type { ComponentProps } from "react";

type AccountSectionProps = ComponentProps<typeof AccountSection>;

interface AccountSectionServerProps {
  account: Omit<AccountSectionProps["account"], "rundown"> & {
    rundown?: ClientRundownData | null;
  };
}

/**
 * Pre-render a ClientRundownData's sections to static HTML strings.
 * Called once per client during SSR in the server component render pass.
 */
function preRenderRundown(rundown: ClientRundownData): RenderedClientRundownData {
  return {
    generatedAt: rundown.generatedAt,
    overallSeverity: rundown.overallSeverity,
    sections: rundown.sections.map((s) => ({
      anchor: s.anchor,
      kind: s.kind,
      title: s.title,
      parentTitle: s.parentTitle,
      renderedHtml: renderToStaticMarkup(
        <GanttSection data={s.data} theme="dark-account-view" />
      ),
    })),
  };
}

export function AccountSectionServer({ account }: AccountSectionServerProps) {
  const { rundown: rawRundown, ...rest } = account as AccountSectionServerProps["account"] & {
    rundown?: ClientRundownData | null;
  };

  const renderedRundown: RenderedClientRundownData | null =
    rawRundown ? preRenderRundown(rawRundown) : null;

  return (
    <AccountSection
      account={{
        ...rest,
        rundown: renderedRundown,
      } as AccountSectionProps["account"]}
    />
  );
}

