/**
 * Server component wrapper for AccountSection.
 *
 * GanttTemplate.tsx and themes.ts use react-dom/server + Node's fs module —
 * they cannot be imported inside a "use client" component. This server
 * component pre-renders each GanttSection to static HTML and passes the
 * rendered strings into AccountSection (client component) via props.
 *
 * This pattern (server component passes pre-rendered HTML strings via props)
 * is the Next.js App Router approach for cases where a client component needs
 * server-only rendered output.
 */

import { renderToStaticMarkup } from "react-dom/server";
import { GanttSection } from "@/lib/runway/gantt/GanttTemplate";
import type { ClientRundownData } from "@/lib/runway/gantt/types";
import type { RenderedClientRundownData } from "../types";
import { AccountSection } from "./account-section";
import type { UnifiedAccount } from "../unified-view";

export interface AccountWithRawRundown extends UnifiedAccount {
  rundown: ClientRundownData | null;
}

/**
 * Pre-render a ClientRundownData's sections to static HTML strings.
 * Called once per client during the server render pass.
 */
function preRenderRundown(rundown: ClientRundownData): RenderedClientRundownData {
  return {
    generatedAt: rundown.generatedAt,
    overallSeverity: rundown.overallSeverity,
    sections: rundown.sections.map((s) => ({
      anchor: s.anchor,
      kind: s.kind,
      title: s.title,
      parentTitle: s.parentTitle,
      renderedHtml: renderToStaticMarkup(
        <GanttSection data={s.data} theme="dark-account-view" />
      ),
    })),
  };
}

export function AccountSectionServer({ account }: { account: AccountWithRawRundown }) {
  const { rundown: rawRundown, ...rest } = account;
  const renderedRundown: RenderedClientRundownData | null = rawRundown
    ? preRenderRundown(rawRundown)
    : null;

  return (
    <AccountSection
      account={{ ...rest, rundown: renderedRundown }}
    />
  );
}

