/**
 * GET /api/runway/gantt-embed?clientId=<id>
 *
 * Returns pre-rendered HTML for all Gantt sections of a single client's
 * rundown. Used by queries-rundown.ts (called from page.tsx server component)
 * during SSR to obtain rendered Gantt HTML.
 *
 * This route handler lives outside the server-component module graph.
 * However, Next.js 16 + Turbopack also prohibits static imports of
 * react-dom/server and anything that transitively imports it (e.g.
 * GanttTemplate.tsx) in ANY App Router entrypoint — including route handlers.
 *
 * Workaround: use dynamic import() for both react-dom/server and GanttTemplate
 * so Turbopack's static module-graph analyser never traces those paths.
 * The modules are resolved at runtime in the Node.js environment where
 * react-dom/server is valid.
 *
 * Auth: RUNWAY_EMBED_SECRET optional shared-secret gate.
 *
 * Response: { generatedAt, overallSeverity, sections: RenderedRundownSection[] }
 */

import { type NextRequest, NextResponse } from "next/server";
import { getRunwayDb } from "@/lib/db/runway";
import { clients, projects as projectsTable } from "@/lib/db/runway-schema";
import { extractClientRundown } from "@/lib/runway/gantt/server";
import { and, asc, eq, isNull } from "drizzle-orm";
import { toISODateString } from "@/app/runway/date-utils";
import type { RenderedRundownSection } from "@/app/runway/types";

const EMBED_SECRET = process.env.RUNWAY_EMBED_SECRET ?? null;

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Optional shared-secret gate (set RUNWAY_EMBED_SECRET in .env.local for prod)
  if (EMBED_SECRET) {
    const auth = request.headers.get("x-embed-secret");
    if (auth !== EMBED_SECRET) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
  }

  const clientId = request.nextUrl.searchParams.get("clientId");
  if (!clientId) {
    return NextResponse.json({ error: "clientId required" }, { status: 400 });
  }

  const db = getRunwayDb();
  const now = new Date();
  const todayISO = toISODateString(now);
  const generatedAt = todayISO;

  // Fetch client
  const [client] = await db.select().from(clients).where(eq(clients.id, clientId)).limit(1);
  if (!client) {
    return NextResponse.json({ error: "Client not found" }, { status: 404 });
  }

  // Fetch top-level projects for this client
  const topLevelProjects = await db
    .select()
    .from(projectsTable)
    .where(and(isNull(projectsTable.parentProjectId), eq(projectsTable.clientId, clientId)))
    .orderBy(asc(projectsTable.sortOrder));

  const rundown = await extractClientRundown(
    db,
    client,
    topLevelProjects,
    generatedAt,
    todayISO,
  );

  // Dynamic imports: bypass Turbopack's static module-graph analyser which
  // prohibits react-dom/server (and GanttTemplate which imports it) in all
  // App Router entrypoints. At runtime the Node.js environment resolves these
  // modules correctly.
  const [{ renderToStaticMarkup }, { createElement }, { GanttSection }] = await Promise.all([
    import("react-dom/server"),
    import("react"),
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — dynamic import breaks Turbopack static trace; types are correct at runtime
    import("@/lib/runway/gantt/GanttTemplate"),
  ]);

  const sections: RenderedRundownSection[] = rundown.sections.map((s) => ({
    anchor: s.anchor,
    kind: s.kind,
    title: s.title,
    parentTitle: s.parentTitle,
    renderedHtml: renderToStaticMarkup(
      createElement(GanttSection, { data: s.data, theme: "dark-account-view" }),
    ),
  }));

  return NextResponse.json({
    generatedAt: rundown.generatedAt,
    overallSeverity: rundown.overallSeverity,
    sections,
  });
}

/**
 * Thin re-export of extractClientRundown from server.ts's pure-logic portion.
 *
 * WHY THIS FILE EXISTS:
 * server.ts imports renderGantt/renderClientRundown from GanttTemplate.tsx,
 * which in turn imports react-dom/server. Next.js 16 + Turbopack forbids
 * react-dom/server in ANY App Router entrypoint's static import graph —
 * including route handlers.
 *
 * extractClientRundown itself does NOT use renderGantt or renderClientRundown.
 * This file re-implements the same function with only the imports it actually
 * needs, so the gantt-embed route handler can import it without pulling in
 * the GanttTemplate → react-dom/server chain.
 *
 * Keep this file in sync with server.ts:extractClientRundown.
 */

import { and, eq, inArray, isNull } from "drizzle-orm";
import { getRunwayDb } from "@/lib/db/runway";
import {
  clients,
  projects as projectsTable,
  weekItems,
} from "@/lib/db/runway-schema";
import {
  detectChildProjectIssues,
} from "@/lib/runway/gantt/detect-issues";
import {
  addSeverity,
  buildL1SectionData,
  buildWrapperSectionData,
  slugAnchor,
} from "@/lib/runway/gantt/section-builders";
import type {
  ClientRow,
  ClientRundownData,
  ProjectRow,
  RundownSection,
  SeverityCounts,
  WeekItemRow,
} from "@/lib/runway/gantt/types";

// ── DB type alias ──────────────────────────────────────────

type DrizzleDb = ReturnType<typeof getRunwayDb>;

const ZERO: SeverityCounts = { critical: 0, warn: 0, info: 0 };

export async function extractClientRundown(
  db: DrizzleDb,
  client: ClientRow,
  topLevelProjects: ProjectRow[],
  generatedAt: string,
  todayISO: string,
): Promise<ClientRundownData> {
  type ClassifiedTop =
    | { kind: "wrapper"; project: ProjectRow; children: ProjectRow[] }
    | { kind: "standalone"; project: ProjectRow };

  const classified: ClassifiedTop[] = [];
  for (const top of topLevelProjects) {
    const children = await db
      .select()
      .from(projectsTable)
      .where(eq(projectsTable.parentProjectId, top.id));
    if (
      top.parentProjectId === null &&
      top.engagementType === "retainer" &&
      children.length > 0
    ) {
      classified.push({ kind: "wrapper", project: top, children });
    } else {
      classified.push({ kind: "standalone", project: top });
    }
  }

  const idsNeedingWeekItems = new Set<string>();
  for (const c of classified) {
    if (c.kind === "wrapper") {
      idsNeedingWeekItems.add(c.project.id);
      for (const child of c.children) idsNeedingWeekItems.add(child.id);
    } else {
      idsNeedingWeekItems.add(c.project.id);
    }
  }

  const wiByProject = new Map<string, WeekItemRow[]>();
  if (idsNeedingWeekItems.size > 0) {
    const all = await db
      .select()
      .from(weekItems)
      .where(inArray(weekItems.projectId, Array.from(idsNeedingWeekItems)));
    for (const w of all) {
      const pid = w.projectId;
      if (!pid) continue;
      const arr = wiByProject.get(pid);
      if (arr) arr.push(w);
      else wiByProject.set(pid, [w]);
    }
  }

  function hasContent(c: ClassifiedTop): boolean {
    if (c.kind === "wrapper") return true;
    return (wiByProject.get(c.project.id) ?? []).length > 0;
  }
  classified.sort((a, b) => {
    const ac = hasContent(a) ? 0 : 1;
    const bc = hasContent(b) ? 0 : 1;
    if (ac !== bc) return ac - bc;
    return a.project.name.localeCompare(b.project.name);
  });

  const sections: RundownSection[] = [];
  const overall: SeverityCounts = { ...ZERO };

  for (const c of classified) {
    if (c.kind === "wrapper") {
      const orphanItems = (wiByProject.get(c.project.id) ?? []).map((w) => ({
        id: w.id,
        title: w.title,
      }));
      const wrapperData = buildWrapperSectionData(
        c.project,
        client,
        c.children,
        orphanItems,
        generatedAt,
        todayISO,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "wrapper",
        title: c.project.name,
        data: wrapperData,
      });
      addSeverity(overall, wrapperData.summary.severity);

      const sortedChildren = [...c.children].sort((a, b) =>
        a.name.localeCompare(b.name),
      );
      for (const child of sortedChildren) {
        const wis = wiByProject.get(child.id) ?? [];
        const relationship = detectChildProjectIssues(child, c.project);
        const extraChart = [...relationship.inline, ...relationship.subRow];
        const childData = buildL1SectionData(
          child,
          client,
          wis,
          todayISO,
          generatedAt,
          extraChart,
        );
        sections.push({
          anchor: slugAnchor(`${c.project.name}-${child.name}`),
          kind: "wrapper-child",
          title: child.name,
          parentTitle: c.project.name,
          data: childData,
        });
        addSeverity(overall, childData.summary.severity);
      }
    } else {
      const wis = wiByProject.get(c.project.id) ?? [];
      const data = buildL1SectionData(
        c.project,
        client,
        wis,
        todayISO,
        generatedAt,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "standalone",
        title: c.project.name,
        data,
      });
      addSeverity(overall, data.summary.severity);
    }
  }

  return {
    client,
    sections,
    generatedAt,
    overallSeverity: overall,
  };
}

/**
 * Self-contained dark-account-view GanttSection renderer.
 *
 * WHY THIS FILE EXISTS:
 * GanttTemplate.tsx imports react-dom/server and themes.ts imports Node's fs.
 * Next.js 16 + Turbopack prohibits ANY file in a App Router entrypoint's
 * static import graph from importing react-dom/server or fs. This restriction
 * applies to route handlers and server components alike — even when those
 * imports are only used in unrelated export paths (e.g. renderGantt).
 *
 * This file extracts exactly the components GanttSection uses when
 * theme === "dark-account-view", with:
 *   - No react-dom/server import
 *   - No themes.ts import (no fs)
 *   - Dark chrome hardcoded: showDataIntegrityPanel=false, showRowAlerts=false
 *
 * Keep in sync with GanttTemplate.tsx: GanttSection, RowBlock, AxisRow,
 * SectionLegendDark, GridLines, computeBarGeometry, computeTodayPosition,
 * and the helper functions they call. When GanttTemplate.tsx changes its
 * rendering logic for the dark theme, mirror those changes here.
 */

import * as React from "react";
import type {
  AnnotatedRow,
  AxisParams,
  GanttData,
} from "./types";

// ── Geometry helpers ─────────────���─────────────────────────

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseISO(s: string): Date {
  return new Date(`${s}T00:00:00Z`);
}

function dayDiff(from: string, to: string): number {
  return Math.round((parseISO(to).getTime() - parseISO(from).getTime()) / MS_PER_DAY);
}

function clampPct(n: number): number {
  if (Number.isNaN(n)) return 0;
  return Math.max(0, Math.min(100, n));
}

type BarGeometry =
  | { kind: "bar"; left: number; width: number }
  | { kind: "milestone"; left: number }
  | { kind: "none" };

export function computeBarGeometry(row: AnnotatedRow, axis: AxisParams): BarGeometry {
  if (axis.kind === "no-axis") return { kind: "none" };
  if (row.startDate === null || row.endDate === null) return { kind: "none" };
  if (row.endDate < row.startDate) return { kind: "none" };
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return { kind: "none" };
  if (row.startDate === row.endDate) {
    const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
    return { kind: "milestone", left };
  }
  const left = clampPct((dayDiff(axis.start, row.startDate) / totalDays) * 100);
  const widthDays = dayDiff(row.startDate, row.endDate) + 1;
  const width = clampPct((widthDays / totalDays) * 100);
  return { kind: "bar", left, width };
}

export function computeTodayPosition(axis: AxisParams): number | null {
  if (axis.kind === "no-axis") return null;
  if (axis.today < axis.start || axis.today >= axis.end) return null;
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return null;
  return clampPct((dayDiff(axis.start, axis.today) / totalDays) * 100);
}

// ── Helpers ─────────────────────────────���──────────────────

function numericDate(iso: string): string {
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return iso;
  return `${parseInt(m[2], 10)}/${parseInt(m[3], 10)}`;
}

function DateOrNull({ value }: { value: string | null }): JSX.Element {
  if (value === null) return <span className="null">null</span>;
  return <span>{numericDate(value)}</span>;
}

function metaLine(row: AnnotatedRow): string {
  const ownerPart = row.owner ? `O: ${row.owner}` : "";
  const resourcesPart = row.resources ?? "";
  return [ownerPart, resourcesPart].filter(Boolean).join(" · ");
}

function rowClass(row: AnnotatedRow): string {
  const classes = ["row"];
  if (row.kind === "weekitem" || row.kind === "project") {
    if (row.status === "completed") classes.push("completed");
    if (row.status === "canceled") classes.push("canceled");
  }
  return classes.join(" ");
}

function inlineDateClass(row: AnnotatedRow): string {
  return row.inline.length > 0 ? "dates bad" : "dates";
}

function statusClass(row: AnnotatedRow): string {
  const status = row.status ?? "scheduled";
  if (status === "scheduled" || status === "not-started" || status === "on-hold") {
    return "scheduled";
  }
  if (status === "at-risk") return "at-risk";
  if (status === "blocked") return "blocked";
  if (status === "awaiting-client") return "scheduled";
  return "active";
}

// ── Day name for data-day attribute ───────────────────────

const WEEKDAY_NAMES = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
] as const;

function getDayName(dateStr: string): string {
  return WEEKDAY_NAMES[parseISO(dateStr).getUTCDay()];
}

// ── Gridlines ─────────────────────────────────────────────

function eachDayBetween(startISO: string, endISO: string): string[] {
  const out: string[] = [];
  const start = new Date(`${startISO}T00:00:00Z`);
  const end = new Date(`${endISO}T00:00:00Z`);
  for (let t = start.getTime(); t < end.getTime(); t += MS_PER_DAY) {
    out.push(new Date(t).toISOString().slice(0, 10));
  }
  return out;
}

function GridLines({ axis }: { axis: AxisParams }): JSX.Element | null {
  if (axis.kind !== "weekly") return null;
  const totalDays = dayDiff(axis.start, axis.end);
  if (totalDays <= 0) return null;
  const days = eachDayBetween(axis.start, axis.end);
  return (
    <>
      {days.map((iso) => {
        const d = new Date(`${iso}T00:00:00Z`);
        const isMonday = d.getUTCDay() === 1;
        const left = clampPct((dayDiff(axis.start, iso) / totalDays) * 100);
        return (
          <div
            key={iso}
            className={`grid-line ${isMonday ? "major" : ""}`.trim()}
            style={{ left: `${left}%` }}
          />
        );
      })}
    </>
  );
}

// ── Axis row ───────────────────────────────��──────────────

function AxisRow({ axis }: { axis: AxisParams }): JSX.Element | null {
  if (axis.kind === "no-axis") return null;
  const totalDays = dayDiff(axis.start, axis.end);
  return (
    <div className="axis-row">
      <div className="axis-spacer" />
      <div className="axis-cells">
        {axis.columns.map((col) => {
          const colLeft = clampPct((dayDiff(axis.start, col.date) / totalDays) * 100);
          return (
            <div
              key={col.date}
              className="axis-cell"
              data-day={getDayName(col.date)}
              style={{ left: `${colLeft}%` }}
            >
              {col.label}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Legend (dark variant) ───────────────────────────────���─

function SectionLegendDark(): JSX.Element {
  return (
    <div className="flex flex-wrap gap-3 items-center text-xs text-slate-400 mb-3">
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm bg-sky-400" /> in-progress
      </span>
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm border border-slate-500/40 bg-slate-500/10" /> scheduled
      </span>
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm bg-amber-400" /> at-risk
      </span>
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm bg-red-400" /> blocked
      </span>
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm bg-emerald-400" /> completed
      </span>
      <span className="inline-flex items-center gap-1.5">
        <span className="inline-block w-7 h-3 rounded-sm bg-slate-400" />{" "}
        <span className="line-through opacity-60">canceled</span>
      </span>
    </div>
  );
}

// ── Row block ─────────────────────────────────────────────
// Dark chrome: showRowAlerts=false — no alert badges or sub-rows.

function RowBlock({
  row,
  axis,
  todayPct,
}: {
  row: AnnotatedRow;
  axis: AxisParams;
  todayPct: number | null;
}): JSX.Element {
  const geom = computeBarGeometry(row, axis);
  const showTodayLine = todayPct !== null && axis.kind !== "no-axis";
  return (
    <>
      <div className={rowClass(row)} data-row-kind={row.kind}>
        <div className="title">{row.title}</div>
        <div className="meta">{metaLine(row)}</div>
        <div className={inlineDateClass(row)}>
          <DateOrNull value={row.startDate} />
          <span> – </span>
          <DateOrNull value={row.endDate} />
        </div>
        <div className="timeline">
          <GridLines axis={axis} />
          {axis.kind !== "no-axis" && showTodayLine && (
            <div className="today-line" style={{ left: `${todayPct}%` }} />
          )}
          {geom.kind === "bar" && (
            <div
              className={`bar ${statusClass(row)}`}
              style={{ left: `${geom.left}%`, width: `${geom.width}%` }}
            />
          )}
          {geom.kind === "milestone" && (
            <div
              className={`milestone ${statusClass(row)}`}
              style={{ left: `${geom.left}%` }}
            />
          )}
        </div>
      </div>
      {/* showRowAlerts=false for dark-account-view — no sub-row alerts */}
    </>
  );
}

// ── GanttSectionDark ──────────────────────────��───────────
// Dark-specific GanttSection: no DataIntegrityPanel, no row alerts.
// Mirrors GanttSection in GanttTemplate.tsx for theme="dark-account-view".

export function GanttSectionDark({ data }: { data: GanttData }): JSX.Element {
  const { rows, axis } = data;
  const todayPct = computeTodayPosition(axis);
  return (
    <>
      <SectionLegendDark />
      {/* showDataIntegrityPanel=false for dark-account-view */}
      <section className="body">
        {axis.kind === "no-axis" && (
          <div className="no-axis-note">
            No dates available — body rendered without a timeline.
          </div>
        )}
        {axis.kind !== "no-axis" && <AxisRow axis={axis} />}

        {rows.map((row) => (
          <RowBlock key={row.id} row={row} axis={axis} todayPct={todayPct} />
        ))}

        {/* Repeat axis at bottom — operator (2026-04-30) */}
        {axis.kind !== "no-axis" && rows.length > 0 && <AxisRow axis={axis} />}
      </section>
    </>
  );
}

/**
 * GET /api/runway/gantt-embed?clientId=<id>
 *
 * Returns pre-rendered HTML for all Gantt sections of a single client's
 * rundown. Used by queries-rundown.ts (called from page.tsx server component)
 * during SSR to obtain rendered Gantt HTML.
 *
 * Module boundary design:
 * GanttTemplate.tsx imports react-dom/server; themes.ts imports Node's fs.
 * Next.js 16 + Turbopack prohibits react-dom/server or fs in ANY App Router
 * entrypoint's static import graph — including route handlers.
 *
 * Solution: this route uses GanttSectionDark from gantt-section-dark.tsx —
 * a self-contained dark-theme renderer that imports neither react-dom/server
 * nor themes.ts. The route calls renderToStaticMarkup directly (allowed in
 * route handlers as long as no OTHER file in the static graph imports it).
 *
 * Auth: RUNWAY_EMBED_SECRET optional shared-secret gate.
 *
 * Response: { generatedAt, overallSeverity, sections: RenderedRundownSection[] }
 */

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { type NextRequest, NextResponse } from "next/server";
import { getRunwayDb } from "@/lib/db/runway";
import { clients, projects as projectsTable } from "@/lib/db/runway-schema";
import { extractClientRundown } from "@/lib/runway/gantt/extract-rundown";
import { GanttSectionDark } from "@/lib/runway/gantt/gantt-section-dark";
import { and, asc, eq, isNull } from "drizzle-orm";
import { toISODateString } from "@/app/runway/date-utils";
import type { RenderedRundownSection } from "@/app/runway/types";

const EMBED_SECRET = process.env.RUNWAY_EMBED_SECRET ?? null;

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Optional shared-secret gate (set RUNWAY_EMBED_SECRET in .env.local for prod)
  if (EMBED_SECRET) {
    const auth = request.headers.get("x-embed-secret");
    if (auth !== EMBED_SECRET) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
  }

  const clientId = request.nextUrl.searchParams.get("clientId");
  if (!clientId) {
    return NextResponse.json({ error: "clientId required" }, { status: 400 });
  }

  const db = getRunwayDb();
  const now = new Date();
  const todayISO = toISODateString(now);
  const generatedAt = todayISO;

  // Fetch client
  const [client] = await db.select().from(clients).where(eq(clients.id, clientId)).limit(1);
  if (!client) {
    return NextResponse.json({ error: "Client not found" }, { status: 404 });
  }

  // Fetch top-level projects for this client
  const topLevelProjects = await db
    .select()
    .from(projectsTable)
    .where(and(isNull(projectsTable.parentProjectId), eq(projectsTable.clientId, clientId)))
    .orderBy(asc(projectsTable.sortOrder));

  const rundown = await extractClientRundown(
    db,
    client,
    topLevelProjects,
    generatedAt,
    todayISO,
  );

  const sections: RenderedRundownSection[] = rundown.sections.map((s) => ({
    anchor: s.anchor,
    kind: s.kind,
    title: s.title,
    parentTitle: s.parentTitle,
    renderedHtml: renderToStaticMarkup(
      createElement(GanttSectionDark, { data: s.data }),
    ),
  }));

  return NextResponse.json({
    generatedAt: rundown.generatedAt,
    overallSeverity: rundown.overallSeverity,
    sections,
  });
}

