// Track 2: build per-client Gantt rundowns and RSC content slots.
// extractClientRundown is imported from extract-rundown.ts (no react-dom/server,
// no fs) so Turbopack's react-server module-condition restriction is satisfied.
// RundownContentRSC renders GanttSectionDark (also clean) as a ReactNode slot
// passed to AccountSection (client component) — no dangerouslySetInnerHTML.
const todayISO = toISODateString(new Date());
const db = getRunwayDb();

// Fan-out: fetch top-level projects per client (one query each).
// allSettled so a single failure doesn't drop the whole page.
const rundownResults = await Promise.allSettled(
  clientsWithProjects.map(async (client) => {
    const topLevelProjects = await db
      .select()
      .from(projectsTable)
      .where(and(isNull(projectsTable.parentProjectId), eq(projectsTable.clientId, client.id)))
      .orderBy(asc(projectsTable.sortOrder));
    const rundown = await extractClientRundown(db, client, topLevelProjects, todayISO, todayISO);
    return { slug: client.slug, rundown };
  })
);

const rundownBySlug = new Map<string, { generatedAt: string; overallSeverity: import("@/lib/runway/gantt/types").SeverityCounts; sections: import("./types").RenderedRundownSection[] }>();
for (const result of rundownResults) {
  if (result.status === "fulfilled") {
    const { slug, rundown } = result.value;
    rundownBySlug.set(slug, {
      generatedAt: rundown.generatedAt,
      overallSeverity: rundown.overallSeverity,
      sections: rundown.sections.map((s) => ({
        anchor: s.anchor,
        kind: s.kind as "wrapper" | "wrapper-child" | "standalone",
        title: s.title,
        parentTitle: s.parentTitle,
      })),
    });
  }
}

const ganttContentBySlug = new Map<string, React.ReactNode>();
for (const result of rundownResults) {
  if (result.status === "fulfilled") {
    const { slug, rundown } = result.value;
    if (rundown.sections.length > 0) {
      ganttContentBySlug.set(slug, <RundownContentRSC sections={rundown.sections} />);
    }
  }
}

const unifiedAccounts = unifiedBase.map((account) => {
  const rundown = rundownBySlug.get(account.slug) ?? null;
  const ganttContent = ganttContentBySlug.get(account.slug);
  return { ...account, rundown, ganttContent };
});

